import collections
import hashlib
import json
from pathlib import Path

root = Path('/private/tmp/fq-trial-stream-screen-20261122')
target = Path('/private/tmp/fq-sabre-trial-stream-20261122/docs/development/evidence')
manifest = json.loads((root/'manifest.json').read_text())
assert manifest['complete'] and not manifest['failures']
manifest['source_commit'] = manifest.pop('sdkbench_commit')
manifest['representation_note'] = 'The archive uses the existing source_commit vocabulary for the original manifest sdkbench_commit field. Report row bytes are unchanged.'
operations = {}
rows = []
sources = []
comparisons = {name: collections.Counter() for name in ('previous', 'reused')}
differences = []
max_error = 0
for entry in manifest['files']:
    raw = (root/entry['name']).read_bytes()
    assert hashlib.sha256(raw).hexdigest() == entry['sha256']
    data = json.loads(raw)
    start = len(rows)
    for row in data:
        costs = {}
        for name, variant in row['variants'].items():
            payload = variant['payload']
            ops = payload['operations']
            digest = hashlib.sha256(json.dumps(ops,separators=(',',':'),allow_nan=False).encode()).hexdigest()
            operations.setdefault(digest, ops)
            variant['payload'] = {'operations_ref': digest, 'final_layout': payload['final_layout'], 'compile_wall_seconds': payload['compile_wall_seconds']}
            metrics = variant['metrics']
            costs[name] = metrics['full_cz_count'], metrics['two_body_dependency_depth']
            max_error = max(max_error, metrics['max_semantic_error'])
        for name in comparisons:
            new, old = costs[name], costs['production']
            label = 'equal' if new == old else 'improved' if all(n<=o for n,o in zip(new,old)) else 'regressed' if all(n>=o for n,o in zip(new,old)) else 'tradeoff'
            comparisons[name][label] += 1
        if len(set(costs.values())) != 1:
            differences.append({'case': row['case'], 'nonce_index': row['nonce_index'], 'costs': costs})
        rows.append(row)
    sources.append({**entry, 'row_range': [start,len(rows)]})
entries = []
chunk = {}
for digest, ops in operations.items():
    proposal = {**chunk, digest: ops}
    if chunk and len(json.dumps(proposal,separators=(',',':')).encode()) > 1300000:
        entries.append(chunk)
        chunk = {}
    chunk[digest] = ops
if chunk: entries.append(chunk)
files = []
for index, chunk in enumerate(entries):
    name = f'sabre-trial-reuse-operations-{index:02d}.json'
    raw = (json.dumps(chunk,separators=(',',':'),allow_nan=False)+'\n').encode()
    (target/name).write_bytes(raw)
    files.append({'name': name, 'sha256': hashlib.sha256(raw).hexdigest(), 'bytes': len(raw)})
for row in rows:
    for variant in row['variants'].values():
        p = variant['payload']
        variant['payload'] = {'operations': operations[p['operations_ref']], 'final_layout': p['final_layout'], 'compile_wall_seconds': p['compile_wall_seconds']}
for entry in sources:
    start,end = entry['row_range']
    raw = (json.dumps(rows[start:end],separators=(',',':'),allow_nan=False)+'\n').encode()
    assert hashlib.sha256(raw).hexdigest() == entry['sha256']
for row in rows:
    for variant in row['variants'].values():
        p = variant['payload']
        digest = hashlib.sha256(json.dumps(p['operations'],separators=(',',':'),allow_nan=False).encode()).hexdigest()
        variant['payload'] = {'operations_ref': digest, 'final_layout': p['final_layout'], 'compile_wall_seconds': p['compile_wall_seconds']}
index = {'manifest': manifest, 'original_files': sources, 'operation_files': files, 'unique_operation_sequences': len(operations), 'rows': rows, 'summary': {'comparisons': {k:dict(v) for k,v in comparisons.items()}, 'changed_cases': differences, 'max_semantic_error': max_error, 'executions': len(rows)*3}, 'screen_driver_source': Path('/private/tmp/fq-trial-stream-screen-20261122.py').read_text(), 'archive_driver_source': Path(__file__).read_text()}
raw = (json.dumps(index,separators=(',',':'),allow_nan=False)+'\n').encode()
assert len(raw) < 1800000
(target/'sabre-trial-reuse-screen.json').write_bytes(raw)
print(json.dumps({'summary': index['summary'], 'unique_operations':len(operations),'operations_bytes':sum(f['bytes'] for f in files),'index_bytes':len(raw)},indent=2))
